// ============================================================================
// TẦM PHÁT HIỆN & TẦM BẮN CỦA ĐƠN VỊ QUÂN TA / ANH HÙNG + GIỚI HẠN BẢN ĐỒ
// - Tầm phát hiện Anh Hùng (HERO): 360 px (5.625 ô bản đồ, tăng từ 190 px)
// - Tầm phát hiện Quân Ta (SOLDIER / ALLY): 320 px (5.0 ô bản đồ, tăng từ 190 px)
// - Tầm bắn Cung Thủ Hoàng Gia (SOLDIER_RANGED): 205 px (~3.20 ô bản đồ)
// ============================================================================
const ALLY_HERO_DETECT_RANGE = 360;
const ALLY_UNIT_DETECT_RANGE = 320;
const ARCHER_ATTACK_RANGE = 205;
const MAP_BOUND_PADDING = 24;

// ============================================================================
// CHỈ SỐ KNOCKBACK CƠ BẢN (MẶC ĐỊNH CỦA ĐÒN ĐÁNH THƯỜNG HIỆN TẠI)
// - Đòn đánh thường cận chiến Quân Ta: 4.0 (Chí mạng: 6.0 = 150% Knockback cơ bản)
// - Đòn đánh thường tầm xa Quân Ta (Cung Thủ): 3.6
// - Đòn đánh thường cận chiến Kẻ Địch: 4.4
// - Đòn đánh thường tầm xa / phép Kẻ Địch: 4.0
// - Hệ số ma sát giảm tốc mỗi frame: 0.72 (dừng khi |knockback| <= 0.2)
// ============================================================================
const BASIC_ATTACK_KNOCKBACK = {
  ALLY_MELEE: 4.0,
  ALLY_MELEE_CRIT: 6.0,
  ALLY_RANGED: 3.6,
  ENEMY_MELEE: 4.4,
  ENEMY_RANGED: 4.0,
  FRICTION_DECAY: 0.72,
} as const;

const LOCKED_CHUNK_PAD = 18;
const LOS_CHUNK_PAD = 14;
const CORNER_WAYPOINT_PAD = 26;

let activeWorldWidthPx =
  INITIAL_KINGDOM_CHUNKS_X * KINGDOM_CHUNK_SIZE * TILE_SIZE;
let activeWorldHeightPx =
  INITIAL_KINGDOM_CHUNKS_Y * KINGDOM_CHUNK_SIZE * TILE_SIZE;
let activeIsFixed30x18Map = false;
let activeKingdomChunksX = INITIAL_KINGDOM_CHUNKS_X;
let activeKingdomChunksY = INITIAL_KINGDOM_CHUNKS_Y;
let activeKingdomUnlockedSet = new Set<string>(
  getDefaultUnlockedChunks(INITIAL_KINGDOM_CHUNKS_X, INITIAL_KINGDOM_CHUNKS_Y)
);

function syncActiveWorldChunkBounds(
  isFixed30x18: boolean,
  chunksX: number,
  chunksY: number,
  unlockedChunks: Iterable<string>
): void {
  activeIsFixed30x18Map = isFixed30x18;
  activeKingdomChunksX = Math.max(1, chunksX);
  activeKingdomChunksY = Math.max(1, chunksY);
  activeWorldWidthPx = isFixed30x18
    ? WORLD_WIDTH
    : activeKingdomChunksX * KINGDOM_CHUNK_SIZE * TILE_SIZE;
  activeWorldHeightPx = isFixed30x18
    ? WORLD_HEIGHT
    : activeKingdomChunksY * KINGDOM_CHUNK_SIZE * TILE_SIZE;
  const nextSet = new Set<string>(unlockedChunks);
  if (nextSet.size === 0) {
    nextSet.add('0,0');
  }
  activeKingdomUnlockedSet = nextSet;
}

const clampWorldX = (x: number): number =>
  Math.max(
    MAP_BOUND_PADDING,
    Math.min(activeWorldWidthPx - MAP_BOUND_PADDING, x)
  );

const clampWorldY = (y: number): number =>
  Math.max(
    MAP_BOUND_PADDING,
    Math.min(activeWorldHeightPx - MAP_BOUND_PADDING, y)
  );

function getChunkWorldRect(
  cx: number,
  cy: number
): { wx0: number; wx1: number; wy0: number; wy1: number } {
  const chunkPx = KINGDOM_CHUNK_SIZE * TILE_SIZE;
  const wx0 = cx * chunkPx;
  const wx1 = (cx + 1) * chunkPx;
  const wy0 = (activeKingdomChunksY - 1 - cy) * chunkPx;
  const wy1 = (activeKingdomChunksY - cy) * chunkPx;
  return { wx0, wx1, wy0, wy1 };
}

function isWorldPointInUnlockedChunk(
  wx: number,
  wy: number,
  lockedPad = LOCKED_CHUNK_PAD
): boolean {
  if (
    wx < MAP_BOUND_PADDING ||
    wx > activeWorldWidthPx - MAP_BOUND_PADDING ||
    wy < MAP_BOUND_PADDING ||
    wy > activeWorldHeightPx - MAP_BOUND_PADDING
  ) {
    return false;
  }
  if (activeIsFixed30x18Map) return true;

  const chunkPx = KINGDOM_CHUNK_SIZE * TILE_SIZE;
  const cx = Math.floor(wx / chunkPx);
  const rowFromTop = Math.floor(wy / chunkPx);
  const cy = activeKingdomChunksY - 1 - rowFromTop;
  if (!activeKingdomUnlockedSet.has(`${cx},${cy}`)) {
    return false;
  }

  if (lockedPad > 0) {
    for (let lcy = 0; lcy < activeKingdomChunksY; lcy++) {
      for (let lcx = 0; lcx < activeKingdomChunksX; lcx++) {
        if (activeKingdomUnlockedSet.has(`${lcx},${lcy}`)) continue;
        const { wx0, wx1, wy0, wy1 } = getChunkWorldRect(lcx, lcy);
        if (
          wx > wx0 - lockedPad &&
          wx < wx1 + lockedPad &&
          wy > wy0 - lockedPad &&
          wy < wy1 + lockedPad
        ) {
          return false;
        }
      }
    }
  }
  return true;
}

// Kẹp tọa độ (wx, wy) vào vùng các Chunk 16×16 đã mở khóa, đồng thời giữ khoảng cách an toàn khỏi mọi cạnh & góc của các Chunk chưa mở khóa
function clampWorldPointToUnlocked(
  wx: number,
  wy: number
): { x: number; y: number } {
  const baseX = clampWorldX(wx);
  const baseY = clampWorldY(wy);
  if (activeIsFixed30x18Map) {
    return { x: baseX, y: baseY };
  }
  if (isWorldPointInUnlockedChunk(baseX, baseY, LOCKED_CHUNK_PAD)) {
    return { x: baseX, y: baseY };
  }

  let bestX = baseX;
  let bestY = baseY;
  let bestDistSq = Infinity;

  activeKingdomUnlockedSet.forEach((key) => {
    const [cxStr, cyStr] = key.split(',');
    const ucx = Number(cxStr) || 0;
    const ucy = Number(cyStr) || 0;
    if (
      ucx < 0 ||
      ucx >= activeKingdomChunksX ||
      ucy < 0 ||
      ucy >= activeKingdomChunksY
    ) {
      return;
    }

    const { wx0, wx1, wy0, wy1 } = getChunkWorldRect(ucx, ucy);
    const hasLeft = activeKingdomUnlockedSet.has(`${ucx - 1},${ucy}`);
    const hasRight = activeKingdomUnlockedSet.has(`${ucx + 1},${ucy}`);
    const hasTop = activeKingdomUnlockedSet.has(`${ucx},${ucy + 1}`);
    const hasBottom = activeKingdomUnlockedSet.has(`${ucx},${ucy - 1}`);

    const minX =
      wx0 + (hasLeft ? 0 : ucx === 0 ? MAP_BOUND_PADDING : LOCKED_CHUNK_PAD);
    const maxX =
      wx1 -
      (hasRight
        ? 0
        : ucx === activeKingdomChunksX - 1
          ? MAP_BOUND_PADDING
          : LOCKED_CHUNK_PAD);
    const minY =
      wy0 +
      (hasTop
        ? 0
        : ucy === activeKingdomChunksY - 1
          ? MAP_BOUND_PADDING
          : LOCKED_CHUNK_PAD);
    const maxY =
      wy1 - (hasBottom ? 0 : ucy === 0 ? MAP_BOUND_PADDING : LOCKED_CHUNK_PAD);

    let candX = Math.max(minX, Math.min(maxX, baseX));
    let candY = Math.max(minY, Math.min(maxY, baseY));

    // Đẩy ra khỏi góc lõm nếu 2 chunk kề cạnh đã mở khóa nhưng chunk chéo góc vẫn đang khóa (trường hợp L-shape)
    for (let lcy = 0; lcy < activeKingdomChunksY; lcy++) {
      for (let lcx = 0; lcx < activeKingdomChunksX; lcx++) {
        if (activeKingdomUnlockedSet.has(`${lcx},${lcy}`)) continue;
        const lRect = getChunkWorldRect(lcx, lcy);
        const fMinX = lRect.wx0 - LOCKED_CHUNK_PAD;
        const fMaxX = lRect.wx1 + LOCKED_CHUNK_PAD;
        const fMinY = lRect.wy0 - LOCKED_CHUNK_PAD;
        const fMaxY = lRect.wy1 + LOCKED_CHUNK_PAD;
        if (
          candX > fMinX &&
          candX < fMaxX &&
          candY > fMinY &&
          candY < fMaxY
        ) {
          const pushLeft = Math.abs(candX - fMinX);
          const pushRight = Math.abs(fMaxX - candX);
          const pushTop = Math.abs(candY - fMinY);
          const pushBottom = Math.abs(fMaxY - candY);
          const minPush = Math.min(pushLeft, pushRight, pushTop, pushBottom);
          if (minPush === pushLeft) candX = fMinX;
          else if (minPush === pushRight) candX = fMaxX;
          else if (minPush === pushTop) candY = fMinY;
          else candY = fMaxY;
        }
      }
    }

    candX = Math.max(minX, Math.min(maxX, candX));
    candY = Math.max(minY, Math.min(maxY, candY));

    const dSq = (candX - wx) * (candX - wx) + (candY - wy) * (candY - wy);
    if (dSq < bestDistSq) {
      bestDistSq = dSq;
      bestX = candX;
      bestY = candY;
    }
  });

  return { x: bestX, y: bestY };
}

function segmentIntersectsBox(
  x0: number,
  y0: number,
  x1: number,
  y1: number,
  minX: number,
  maxX: number,
  minY: number,
  maxY: number
): boolean {
  let t0 = 0;
  let t1 = 1;
  const dx = x1 - x0;
  const dy = y1 - y0;
  const p = [-dx, dx, -dy, dy];
  const q = [x0 - minX, maxX - x0, y0 - minY, maxY - y0];
  for (let i = 0; i < 4; i++) {
    if (Math.abs(p[i]) < 1e-8) {
      if (q[i] < 0) return false;
    } else {
      const t = q[i] / p[i];
      if (p[i] < 0) {
        if (t > t1) return false;
        if (t > t0) t0 = t;
      } else {
        if (t < t0) return false;
        if (t < t1) t1 = t;
      }
    }
  }
  return t0 <= t1;
}

function doesSegmentCrossLockedChunk(
  x0: number,
  y0: number,
  x1: number,
  y1: number,
  pad = LOS_CHUNK_PAD
): { blocked: boolean; hitCx: number; hitCy: number } {
  if (activeIsFixed30x18Map) {
    return { blocked: false, hitCx: -1, hitCy: -1 };
  }
  let bestDistSq = Infinity;
  let hitCx = -1;
  let hitCy = -1;
  for (let lcy = 0; lcy < activeKingdomChunksY; lcy++) {
    for (let lcx = 0; lcx < activeKingdomChunksX; lcx++) {
      if (activeKingdomUnlockedSet.has(`${lcx},${lcy}`)) continue;
      const { wx0, wx1, wy0, wy1 } = getChunkWorldRect(lcx, lcy);
      if (
        segmentIntersectsBox(
          x0,
          y0,
          x1,
          y1,
          wx0 - pad,
          wx1 + pad,
          wy0 - pad,
          wy1 + pad
        )
      ) {
        const cxMid = (wx0 + wx1) * 0.5;
        const cyMid = (wy0 + wy1) * 0.5;
        const dSq = (cxMid - x0) * (cxMid - x0) + (cyMid - y0) * (cyMid - y0);
        if (dSq < bestDistSq) {
          bestDistSq = dSq;
          hitCx = lcx;
          hitCy = lcy;
        }
      }
    }
  }
  return { blocked: hitCx !== -1, hitCx, hitCy };
}

// Tự động bẻ lái đường đi vòng qua góc của Chunk chưa mở khóa khi đơn vị di chuyển giữa 2 Chunk đã mở khóa (ví dụ cấu trúc chữ L)
function resolveSteeredMoveTarget(
  ux: number,
  uy: number,
  rawTargetX: number,
  rawTargetY: number
): { x: number; y: number } {
  const safeTarget = clampWorldPointToUnlocked(rawTargetX, rawTargetY);
  if (activeIsFixed30x18Map) {
    return safeTarget;
  }

  const check = doesSegmentCrossLockedChunk(
    ux,
    uy,
    safeTarget.x,
    safeTarget.y,
    LOS_CHUNK_PAD
  );
  if (!check.blocked) {
    return safeTarget;
  }

  const { wx0, wx1, wy0, wy1 } = getChunkWorldRect(check.hitCx, check.hitCy);
  const corners = [
    { x: wx0 - CORNER_WAYPOINT_PAD, y: wy0 - CORNER_WAYPOINT_PAD },
    { x: wx1 + CORNER_WAYPOINT_PAD, y: wy0 - CORNER_WAYPOINT_PAD },
    { x: wx0 - CORNER_WAYPOINT_PAD, y: wy1 + CORNER_WAYPOINT_PAD },
    { x: wx1 + CORNER_WAYPOINT_PAD, y: wy1 + CORNER_WAYPOINT_PAD },
  ];

  let bestCorner: { x: number; y: number } | null = null;
  let bestScore = Infinity;

  for (const c of corners) {
    if (!isWorldPointInUnlockedChunk(c.x, c.y, LOCKED_CHUNK_PAD - 2)) continue;
    const dToCorner = Math.hypot(c.x - ux, c.y - uy);
    if (dToCorner <= 6) continue;
    const subCheck = doesSegmentCrossLockedChunk(
      ux,
      uy,
      c.x,
      c.y,
      LOS_CHUNK_PAD - 2
    );
    if (!subCheck.blocked) {
      const totalScore =
        dToCorner + Math.hypot(safeTarget.x - c.x, safeTarget.y - c.y);
      if (totalScore < bestScore) {
        bestScore = totalScore;
        bestCorner = c;
      }
    }
  }

  if (bestCorner) {
    return bestCorner;
  }

  return safeTarget;
}

// Bước di chuyển an toàn: Nếu bước tiếp theo chạm vào Chunk chưa mở khóa thì tự động trượt dọc theo mép biên và kẹp ngoài vùng khóa
function stepWorldPositionInUnlockedChunks(
  fromX: number,
  fromY: number,
  nextX: number,
  nextY: number
): { x: number; y: number } {
  if (activeIsFixed30x18Map) {
    return { x: clampWorldX(nextX), y: clampWorldY(nextY) };
  }
  if (isWorldPointInUnlockedChunk(nextX, nextY, LOCKED_CHUNK_PAD)) {
    return { x: nextX, y: nextY };
  }
  const canSlideX = isWorldPointInUnlockedChunk(nextX, fromY, LOCKED_CHUNK_PAD);
  const canSlideY = isWorldPointInUnlockedChunk(fromX, nextY, LOCKED_CHUNK_PAD);
  if (canSlideX && !canSlideY) {
    return { x: nextX, y: fromY };
  }
  if (canSlideY && !canSlideX) {
    return { x: fromX, y: nextY };
  }
  return clampWorldPointToUnlocked(nextX, nextY);
}

// ============================================================================
// HỆ TỌA ĐỘ GÓC NHÌN ISOMETRIC 2.5D (TỈ LỆ KIM CƯƠNG CHUẨN 2:1)
// - Giữ nguyên 100% logic mô phỏng thế giới 2D (wx, wy)
// - Ánh xạ sang mặt phẳng Isometric (isoX, isoY) và ngược lại theo thời gian thực
// ============================================================================
const ISO_ORIGIN_X = WORLD_WIDTH / 2; // 960
const ISO_ORIGIN_Y = WORLD_HEIGHT / 2; // 576
const ISO_COS = 0.75; // Mỗi ô 64x64 thành hình thoi rộng 96px, cao 48px (tỉ lệ 2:1)
const ISO_SIN = 0.375;

function worldToIso(wx: number, wy: number): { x: number; y: number } {
  const dx = wx - ISO_ORIGIN_X;
  const dy = wy - ISO_ORIGIN_Y;
  return {
    x: ISO_ORIGIN_X + (dx - dy) * ISO_COS,
    y: ISO_ORIGIN_Y + (dx + dy) * ISO_SIN,
  };
}

function isoToWorld(ix: number, iy: number): { x: number; y: number } {
  const du = (ix - ISO_ORIGIN_X) / ISO_COS;
  const dv = (iy - ISO_ORIGIN_Y) / ISO_SIN;
  return {
    x: ISO_ORIGIN_X + (du + dv) * 0.5,
    y: ISO_ORIGIN_Y + (dv - du) * 0.5,
  };
}

function applyIsoGroundTransform(ctx: CanvasRenderingContext2D) {
  ctx.translate(ISO_ORIGIN_X, ISO_ORIGIN_Y);
  ctx.transform(ISO_COS, ISO_SIN, -ISO_COS, ISO_SIN, 0, 0);
  ctx.translate(-ISO_ORIGIN_X, -ISO_ORIGIN_Y);
}

// Khung bao hình học động của bản đồ kim cương Isometric 2.5D theo kích thước hiện tại (worldW, worldH)
// - Điểm A (Góc dưới bên trái - Điểm gốc): worldToIso(0, worldH)
// - Điểm B (Góc trên): worldToIso(0, 0)
// - Điểm C (Góc phải): worldToIso(worldW, 0)
// - Điểm D (Góc dưới): worldToIso(worldW, worldH)
function getDynamicIsoBounds(worldW: number, worldH: number) {
  const pA = worldToIso(0, worldH);
  const pB = worldToIso(0, 0);
  const pC = worldToIso(worldW, 0);
  const pD = worldToIso(worldW, worldH);
  const minX = pA.x - 90;
  const maxX = pC.x + 240;
  const minY = pB.y - 90;
  const maxY = pD.y + 110;
  return {
    pA,
    pB,
    pC,
    pD,
    minX,
    maxX,
    minY,
    maxY,
    spanW: Math.max(400, maxX - minX),
    spanH: Math.max(300, maxY - minY),
  };
}

interface KingdomChunkExpandButtonIso {
  key: string;
  targetCx: number;
  targetCy: number;
  directionLabel: string;
  cx: number;
  cy: number;
  w: number;
  h: number;
  connectors: Array<{ x: number; y: number }>;
}

// Tạo danh sách các nút Mở Rộng Đất Vương Quốc cho TỪNG Chunk 16×16 nằm kề các cạnh B-C và C-D của các chunk đã mở
// Ví dụ: Đang có 2 chunk kề nhau tạo thành cạnh dài 2 chunk -> Hiển thị đủ 2 nút mở rộng riêng biệt cho 2 chunk đó
function getKingdomChunkExpansionButtonsIso(
  chunksX: number,
  chunksY: number,
  unlockedChunks: Iterable<string>
): KingdomChunkExpandButtonIso[] {
  const safeChunksX = Math.max(1, chunksX);
  const safeChunksY = Math.max(1, chunksY);
  const gridRows = safeChunksY * KINGDOM_CHUNK_SIZE;
  const chunkPx = KINGDOM_CHUNK_SIZE * TILE_SIZE;
  const unlockedSet = new Set(unlockedChunks);
  if (unlockedSet.size === 0) {
    unlockedSet.add('0,0');
  }

  const buttons: KingdomChunkExpandButtonIso[] = [];

  for (let targetCy = 0; targetCy <= safeChunksY; targetCy++) {
    for (let targetCx = 0; targetCx <= safeChunksX; targetCx++) {
      const key = `${targetCx},${targetCy}`;
      if (unlockedSet.has(key)) continue;

      const hasNeighborBC =
        targetCy > 0 && unlockedSet.has(`${targetCx},${targetCy - 1}`);
      const hasNeighborCD =
        targetCx > 0 && unlockedSet.has(`${targetCx - 1},${targetCy}`);
      if (!hasNeighborBC && !hasNeighborCD) continue;

      const wx0 = targetCx * chunkPx;
      const wx1 = (targetCx + 1) * chunkPx;
      const wy0 = (gridRows - (targetCy + 1) * KINGDOM_CHUNK_SIZE) * TILE_SIZE;
      const wy1 = (gridRows - targetCy * KINGDOM_CHUNK_SIZE) * TILE_SIZE;

      const connectors: Array<{ x: number; y: number }> = [];
      let cx = 0;
      let cy = 0;
      let directionLabel = 'B–C';

      if (hasNeighborBC && hasNeighborCD) {
        const edgeBC = worldToIso((wx0 + wx1) * 0.5, wy1);
        const edgeCD = worldToIso(wx0, (wy0 + wy1) * 0.5);
        connectors.push(edgeBC, edgeCD);
        const pocketPt = worldToIso(
          wx0 + chunkPx * 0.35,
          wy1 - chunkPx * 0.35
        );
        cx = pocketPt.x;
        cy = pocketPt.y;
        directionLabel = 'B–C / C–D';
      } else if (hasNeighborBC) {
        const edgeBC = worldToIso((wx0 + wx1) * 0.5, wy1);
        connectors.push(edgeBC);
        cx = edgeBC.x + 88;
        cy = edgeBC.y - 48;
        directionLabel = 'B–C';
      } else {
        const edgeCD = worldToIso(wx0, (wy0 + wy1) * 0.5);
        connectors.push(edgeCD);
        cx = edgeCD.x + 92;
        cy = edgeCD.y + 50;
        directionLabel = 'C–D';
      }

      buttons.push({
        key,
        targetCx,
        targetCy,
        directionLabel,
        cx,
        cy,
        w: 196,
        h: 48,
        connectors,
      });
    }
  }

  return buttons;
}


type FormationMode =
  | 'CLUSTER'
  | 'VERTICAL'
  | 'HORIZONTAL'
  | 'DIAGONAL_VERTICAL'
  | 'DIAGONAL_HORIZONTAL'
  | 'CIRCLE';

const FORMATION_ORDER: FormationMode[] = [
  'CLUSTER',
  'VERTICAL',
  'HORIZONTAL',
  'DIAGONAL_VERTICAL',
  'DIAGONAL_HORIZONTAL',
  'CIRCLE',
];

