const INITIAL_BUILDINGS: PlacedBuilding[] = [
  {
    id: 'b-init-warehouse',
    type: 'WAREHOUSE',
    gridX: 7,
    gridY: 7,
    level: 1,
    buildProgress: 100,
    isConstructed: true,
    lastProducedAt: Date.now(),
  },
];

function createInitialResourceNodes(
  existingBuildings: PlacedBuilding[] = INITIAL_BUILDINGS,
  mapSeed = 20261030,
  chunksX = INITIAL_KINGDOM_CHUNKS_X,
  chunksY = INITIAL_KINGDOM_CHUNKS_Y,
  unlockedChunks?: Iterable<string>
): ResourceNode[] {
  const unlockedSet = unlockedChunks
    ? new Set(unlockedChunks)
    : new Set(getDefaultUnlockedChunks(chunksX, chunksY));
  const terrain = generateProceduralKingdomTerrain(
    mapSeed,
    chunksX,
    chunksY,
    existingBuildings,
    unlockedSet
  );
  setActiveKingdomTerrainLayout(
    terrain.waterTiles,
    terrain.roadTiles,
    terrain.gridCols,
    terrain.gridRows
  );
  clearKingdomChunkCache();
  const allNodes: ResourceNode[] = [];
  for (let cy = 0; cy < chunksY; cy++) {
    for (let cx = 0; cx < chunksX; cx++) {
      if (!unlockedSet.has(`${cx},${cy}`)) continue;
      const chunkNodes = generateProceduralResourcesForChunk(
        mapSeed,
        cx,
        cy,
        terrain.gridRows,
        terrain.waterTiles,
        terrain.roadTiles,
        existingBuildings,
        allNodes
      );
      allNodes.push(...chunkNodes);
    }
  }
  return allNodes;
}

// Kiểm tra công trình bị giới hạn xây tối đa 1 cái (Mọi công trình đều giới hạn 1, trừ Ruộng Lúa FARM, Nhà Dân TOWN_HALL, Lửa Trại CAMPFIRE và 4 loại Tháp Phòng Thủ)
function isSingleLimitBuildingType(bType: BuildingType): boolean {
  return (
    bType !== 'FARM' &&
    bType !== 'TOWN_HALL' &&
    bType !== 'CAMPFIRE' &&
    !isDefensiveTowerBuilding(bType)
  );
}

function getVillagerArchetypeId(u: VillagerUnit): AllyUnitArchetypeId {
  if (u.role === 'HERO') return u.heroArchetypeId || 'KING';
  if (u.role === 'PEASANT') return 'PEASANT';
  return u.combatClass === 'RANGED' ? 'SOLDIER_RANGED' : 'SOLDIER_MELEE';
}

