  const triggerLightningBolt = useCallback(() => {
    const startX = 160 + Math.random() * (CANVAS_WIDTH - 320);
    let currX = startX;
    let currY = 0;
    const segments: Array<{ x1: number; y1: number; x2: number; y2: number }> =
      [];
    const steps = 9 + Math.floor(Math.random() * 5);
    const targetY = 300 + Math.random() * 260;
    const stepY = targetY / steps;

    for (let i = 0; i < steps; i++) {
      const nextX = currX + (Math.random() - 0.5) * 68;
      const nextY = currY + stepY;
      segments.push({ x1: currX, y1: currY, x2: nextX, y2: nextY });
      // Occasional side branch fork
      if (i > 1 && i < steps - 1 && Math.random() < 0.45) {
        const bx = nextX + (Math.random() > 0.5 ? 1 : -1) * (28 + Math.random() * 40);
        const by = nextY + stepY * (1.2 + Math.random());
        segments.push({ x1: nextX, y1: nextY, x2: bx, y2: by });
      }
      currX = nextX;
      currY = nextY;
    }

    lightningRef.current.flashAlpha = 0.82;
    lightningRef.current.boltSegments = segments;
    lightningRef.current.nextStrikeAt =
      performance.now() + 2600 + Math.random() * 3400;
    soundFX.playThunder();
  }, []);

