                          const rangedCardQty =
                            inventoryItems.find(
                              (it) => it.unitCardType === 'SOLDIER_RANGED'
                            )?.quantity || 0;
                          const isCapFull =
                            currentSoldiersInKingdom >= maxSoldierCapacity;
                          const canTrainMelee = meleeCardQty > 0 && !isCapFull;
